      c.quadraticCurveTo(cx, y - 0.25, cx - 3.6, y + 0.45);
      c.closePath();
      
      const g = c.createRadialGradient(cx - 1.2, y - 2.0, 0.2, cx, y - 0.5, 3.8);
      g.addColorStop(0, A.lite);
      g.addColorStop(0.5, A.mat);
      g.addColorStop(1, adjustL(A.dark, -12));
      c.fillStyle = g; c.fill();

      ellipsePath(c, cx, y - 2.7, 0.42, 0.22);
      c.fillStyle = A.alt(A.realce); c.fill();

      c.beginPath();
      c.moveTo(cx - 3.7, y + 0.25);
      c.quadraticCurveTo(cx, y + 1.2, cx + 4.2, y + 0.4);
      c.quadraticCurveTo(cx + 4.3, y + 1.0, cx + 3.8, y + 1.25);
      c.quadraticCurveTo(cx, y + 1.8, cx - 3.9, y + 0.95);
      c.quadraticCurveTo(cx - 4.1, y + 0.6, cx - 3.7, y + 0.25);
