      const vg = c.createLinearGradient(cx - 3.5, y + 0.2, cx + 3.5, y + 1.6);
      vg.addColorStop(0, A.alt(A.dark));
      vg.addColorStop(0.5, A.alt(A.mat));
      vg.addColorStop(1, adjustL(A.alt(A.dark), -15));
      c.fillStyle = vg; c.fill();
      
      c.beginPath();
      c.moveTo(cx - 3.9, y + 0.95);
      c.quadraticCurveTo(cx, y + 1.8, cx + 3.8, y + 1.25);
      c.lineWidth = 0.25;
      c.strokeStyle = adjustL(A.alt(A.dark), -20);
