      c.beginPath();
      c.moveTo(cx - 0.5, y - 0.1); c.quadraticCurveTo(cx + 1.0, y - 2.0, cx + 3.0, y - 2.5);
      c.lineWidth = 0.4; c.strokeStyle = withA(adjustL(tela, -35), 0.4); c.stroke();
      
