      c.quadraticCurveTo(cx, y - 1.2, cx + 3.4, y - 1.0);
      c.quadraticCurveTo(cx + 3.7, y - 1.0, cx + 3.7, y + 0.1);
      c.quadraticCurveTo(cx, y + 1.0, cx - 3.7, y + 0.1);
