  let _coreoTopbar = null;
  function coreoTopbar() {
    if (!_coreoTopbar) {
      _coreoTopbar = coreografias({
        draw: drawF, el: canvas, emit: emitParticle, burst: burstParticles,
        mirar: mirarA, desliza: true,
      });
    }
    return _coreoTopbar;
  }

  let bubbleActive = false;
  let bubbleTimer  = null;

  function hideAdvice() {
    if (!bubble) return;
    bubble.classList.remove('show');
    bubbleActive = false;
  }

  async function triggerAdvice(forcedText) {
    if (!enabled || !adviceEnabled || !bubble || isBusy) return;
    if (bubbleTimer) clearTimeout(bubbleTimer);

    const text = forcedText || CONSEJOS[rand(0, CONSEJOS.length - 1)];

    const b = getBounds();
    if (b) {
      const mid = b.left + (b.right - b.left) / 2;
      bubble.className = getX() < mid ? 'plt-bubble-right show' : 'plt-bubble-left show';
    } else {
      bubble.className = 'plt-bubble-right show';
    }

    bubble.innerHTML = '';
    bubbleActive = true;

    const promptSpan = document.createElement('span');
    promptSpan.className = 'plt-prompt';
    promptSpan.textContent = '> ';
    bubble.appendChild(promptSpan);

    const textContainer = document.createElement('span');
    bubble.appendChild(textContainer);

    const cursor = document.createElement('span');
    cursor.className = 'plt-cursor';
    bubble.appendChild(cursor);

    let typingFinished = false;

    const animPromise = (async () => {
      if (isBusy) return;
      drawF('laptopOpen');
      await wait(300);
      let frameToggle = false;
      while (bubbleActive && !typingFinished && !isBusy) {
        frameToggle = !frameToggle;
        drawF(frameToggle ? 'laptopType1' : 'laptopType2');
        await wait(120 + Math.random() * 80);
      }
      while (bubbleActive && !isBusy) {
        drawF(Math.random() < 0.3 ? (Math.random() < 0.5 ? 'laptopType1' : 'laptopType2') : 'laptopOpen');
        await wait(400);
      }
      if (isBusy) return;
      drawF('laptopOpen'); await wait(300);
      drawF('happyBlink'); await wait(80);
      drawF('happy');      await wait(400);
      drawF('base');
    })();

    const chars = Array.from(text);
    for (let idx = 0; idx < chars.length; idx++) {
      if (!bubbleActive || isBusy) break;
      const ch = chars[idx];
      const span = document.createElement('span');
      span.className = 'plt-char';
      if (ch === ' ') { span.innerHTML = '&nbsp;'; } else { span.textContent = ch; }
      textContainer.appendChild(span);
      await wait(20);
    }

    typingFinished = true;

    const duration = Math.min(12000, Math.max(5000, text.length * 60 + 3000));
    await new Promise(resolve => {
      bubbleTimer = setTimeout(() => { hideAdvice(); resolve(); }, duration);
      const check = setInterval(() => {
        if (!bubbleActive) { clearInterval(check); resolve(); }
      }, 100);
    });

    await animPromise;
  }

  let _blinkTimer = null;
  function startBlinkTimer() {
    if (_blinkTimer) return;
    function tick() {
      _blinkTimer = setTimeout(() => {
        if (enabled && !isBusy && !isNear && !isWalking) {
          drawF('blink');
          setTimeout(() => { if (!isBusy && !isWalking) drawF('base'); }, 75);
        }
        tick();
      }, rand(1000, 2200));
    }
    tick();
  }


  async function doStopGestures(n) {
    if (isBusy) return;
    isBusy = true;
    if (canvas) canvas.classList.remove('plt-idle');
    try {
      const T = coreoTopbar();
      for (let i = 0; i < n; i++) {
        if (!enabled || paused) break;
        const g = T.elegir();
        await g();
        await wait(rand(450, 950));
      }
    } finally {
      isBusy = false;
      if (canvas && !paused && !isWalking) canvas.classList.add('plt-idle');
    }
  }

  async function loop() {
    await wait(rand(2500, 4500));
    while (true) {
      if (!enabled) { await wait(500); continue; }
      if (_staged) { await wait(500); continue; }
      if (isBusy) { await wait(150); continue; }
      if (paused) { await wait(200); continue; }
      if (bubbleActive) { await wait(500); continue; }

      const np = getPal();
      if (np !== pal) {
        pal = np; resolveHatColors();
        if (!_fxRAF) canvas.style.filter = staticBodyFilter();
      }

      const b = getBounds();
      if (!b || (b.right - b.left < 100)) {
        wrap.style.display = 'none';
        await wait(1000);
        continue;
      }
      wrap.style.display = enabled ? '' : 'none';

      const cx = getX();
      if (cx < b.left || cx > b.right) setX(Math.max(b.left, Math.min(b.right, cx)));

      const msgCount = Math.random() < 0.55 ? 1 : 0;
      for (let i = 0; i < msgCount; i++) {
        if (!enabled || paused) break;
        isBusy = true;
        try { await coreoTopbar().laptop(); } finally { isBusy = false; }
        if (!enabled) break;
        await wait(rand(700, 1500));
      }

      if (!paused && enabled) {
        await walkRouteWithStops();
      }
    }
  }

  async function walkRouteWithStops() {
    const b = getBounds();
    if (!b) return;
    const startX = getX();
    const dest = Math.abs(startX - b.left) < Math.abs(startX - b.right) ? b.right : b.left;

    const stops = rand(2, 3);
    for (let s = 1; s <= stops; s++) {
      if (paused || !enabled) return;
      const frac  = s / (stops + 1);
      const stopX = startX + (dest - startX) * frac;
      await walkTo(stopX);
      if (paused || !enabled) return;
      await wait(rand(250, 600));
      await doStopGestures(rand(2, 3));
      if (paused || !enabled) return;
      await wait(rand(300, 700));
    }

    if (paused || !enabled) return;
    await walkTo(dest);
    await wait(rand(900, 1700));
  }

  let hoverLeaveTimer = null;

  function onTopbarMove(e) {
    if (!enabled) return;
    const wRect = wrap.getBoundingClientRect();
    const dist  = e.clientX - (wRect.left + wRect.width / 2);
    const abs   = Math.abs(dist);

    if (abs < 68) {
      if (!isNear) { isNear = true; paused = true; stopLegs(); clearTimeout(hoverLeaveTimer); if (canvas) canvas.classList.remove('plt-idle'); }
      if (!isBusy) drawF(dist < -6 ? 'lookL' : dist > 6 ? 'lookR' : 'lookU');
    } else if (abs > 100 && isNear) {
      isNear = false;
      clearTimeout(hoverLeaveTimer);
      hoverLeaveTimer = setTimeout(() => {
        if (!isBusy) { drawF('blink'); setTimeout(() => { if (!isBusy && !isNear) drawF('base'); }, 70); }
        paused = false;
        if (canvas && !isBusy && !isWalking) canvas.classList.add('plt-idle');
      }, 200);
    }
  }

  async function runTo(targetX, ignorePause = false) {
    if (paused && !ignorePause) return;
    const b = getBounds();
    if (!b) return;
    targetX = Math.max(b.left, Math.min(b.right, targetX));
    if (Math.abs(targetX - getX()) < 8) return;

    mirarA(targetX > getX() ? 'fr' : 'fl');
    isWalking = true;
    if (canvas) canvas.classList.remove('plt-idle');

    stopLegs();
    legPhase = 0;
    legTimer = setInterval(() => {
      legPhase = (legPhase + 1) % 2;
      drawF(legPhase === 0 ? 'walk1' : 'walk2');
    }, 110);
    
    await moveTo(targetX, 110, ignorePause);
    stopLegs();
    isWalking = false;
    if (!paused || ignorePause) drawF('base');
  }

  async function onCanvasClick(e) {
    if (!enabled || isBusy) return;
    e.preventDefault();

    isBusy = true; isNear = false; paused = true;
    stopLegs();
    if (canvas) canvas.classList.remove('plt-idle');
    hideAdvice();

    try {
      const T = coreoTopbar();
      const picks = [T.celebrate, T.wave, T.nod, T.think, T.curiosity, T.coffee, T.bubble,
                     T.dance, T.love, T.dizzy, T.magnify, T.sneeze];
      const g = picks[Math.floor(Math.random() * picks.length)];
      await g();
    } finally {
      paused = false; isBusy = false; drawF('base'); if (canvas) canvas.classList.add('plt-idle');
    }
  }

